SELECT     th.TSF_NO as \"Transfer Number\",     th.STATUS,     th.TSF_TYPE as \"Transfer Type\",     th.FROM_LOC as \"From Location\",     th.FROM_LOC_TYPE as \"From Location Type\",     CASE th.FROM_LOC_TYPE WHEN 'S' THEN stf.STORE_NAME WHEN 'W' THEN whf.WH_NAME END as \"From Location Name\",     th.TO_LOC as \"To Location\",     th.TO_LOC_TYPE as \"To Loc Type\",     CASE th.TO_LOC_TYPE WHEN 'S' THEN stt.STORE_NAME WHEN 'W' THEN wht.WH_NAME END as \"To Location Name\",     th.CREATE_DATE as \"Create Date\",     th.APPROVAL_DATE as \"Approval Date\",     th.EXP_DC_DATE as \"Expected DC Date\",     th.DELIVERY_DATE as \"Delivery Date\",     td.ITEM,     im.ITEM_DESC as \"Item Description\",     im.DEPT as DEPARTMENT,     d.DEPT_NAME as \"Department Name\",     td.TSF_QTY as \"Transfer Qty\",     td.SHIP_QTY as \"Shipment Qty\",     td.RECEIVED_QTY as \"Received Qty\",     td.SHIP_QTY - td.RECEIVED_QTY AS \"Outstanding Qty\",     td.TSF_COST as \"Transfer Cost\" FROM rds_wv_tsfhead th INNER JOIN rds_wv_tsfdetail td ON th.TSF_NO = td.TSF_NO INNER JOIN rds_wv_item_master im ON td.ITEM = im.ITEM LEFT JOIN rds_wv_deps d ON im.DEPT = d.DEPT LEFT JOIN rds_wv_store stf ON th.FROM_LOC = stf.STORE AND th.FROM_LOC_TYPE = 'S' LEFT JOIN rds_wv_wh whf ON th.FROM_LOC = whf.WH AND th.FROM_LOC_TYPE = 'W' LEFT JOIN rds_wv_store stt ON th.TO_LOC = stt.STORE AND th.TO_LOC_TYPE = 'S' LEFT JOIN rds_wv_wh wht ON th.TO_LOC = wht.WH AND th.TO_LOC_TYPE = 'W' WHERE th.STATUS NOT IN ('C', 'D') </ds:dbquery><ds:target_type>Oracle 12c</ds:target_type><ds:object_name/></ds:dataptr><ds:columns><ds:column><ds:name>Transfer Number</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>STATUS</ds:name><ds:datatype>varchar(1)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Transfer Type</ds:name><ds:datatype>varchar(6)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>From Location</ds:name><ds: